  "signup_request_group",
  {
    signupRequestId: uuid("signup_request_id")
      .notNull()
      .references(() => signupRequest.id, { onDelete: "cascade" }),
    groupId: text("group_id").notNull(),
    groupEmail: text("group_email").notNull(),
    role: text().notNull().default("member"),
