import "server-only";

import { eq } from "drizzle-orm";
import { z } from "zod";

import { db } from "@/lib/db";
import { workspaceIdentity } from "@/lib/schema";

const identitySchema = z.object({
  sub: z.string().min(1).max(255),
  hd: z.string().min(1),
  email: z.email(),
  email_verified: z.literal(true),
});

const profileSchema = z.object({
  id: z.string().min(1),
  primaryEmail: z.email(),
  name: z.object({ fullName: z.string() }).optional(),
  thumbnailPhotoUrl: z.url().optional(),
});

const roleAssignmentsSchema = z.object({
  items: z.array(z.object({ roleId: z.string() })).optional(),
  nextPageToken: z.string().optional(),
});

export class WorkspaceUnavailable extends Error {
  constructor(public readonly reconnect = false) {
    super(reconnect ? "Reconnect your Google account" : "Workspace unavailable");
  }
}

export function validateIdentity(input: unknown) {
  const identity = identitySchema.parse(input);
  if (!process.env.GOOGLE_WORKSPACE_DOMAIN || identity.hd !== process.env.GOOGLE_WORKSPACE_DOMAIN)
    throw new WorkspaceUnavailable(true);
  return identity;
}

async function googleGet(url: string, accessToken: string) {
  const response = await fetch(url, {
    headers: { Authorization: `Bearer ${accessToken}` },
    cache: "no-store",
    signal: AbortSignal.timeout(10_000),
  });
  if (!response.ok) {
    await logGoogleFailure(url, response);
    throw new WorkspaceUnavailable(response.status === 401);
  }
  return response.json();
}

async function logGoogleFailure(url: string | URL, response: Response) {
  const parsed = z
    .object({
      error: z.object({
        errors: z
          .array(
            z.object({
              reason: z
                .string()
                .regex(/^[\w.]+$/)
                .max(100),
            }),
          )
          .optional(),
      }),
    })
    .safeParse(await response.json().catch(() => null));
  console.error("[workspace] Google API rejected request", {
    endpoint: new URL(url).pathname.replace(/\/users\/[^/]+/, "/users/{userKey}"),
    status: response.status,
    reasons: parsed.success ? parsed.data.error.errors?.map(({ reason }) => reason) : undefined,
  });
}

export async function readWorkspaceProfile(
  accessToken: string,
  subject: string,
  allowInitialBinding = false,
) {
  const identity = validateIdentity(
    await googleGet("https://openidconnect.googleapis.com/v1/userinfo", accessToken),
  );
  if (identity.sub !== subject) throw new WorkspaceUnavailable(true);

  const [binding] = await db
    .select()
    .from(workspaceIdentity)
    .where(eq(workspaceIdentity.googleSubject, subject));
  if (!binding && !allowInitialBinding) throw new WorkspaceUnavailable(true);

  const url = new URL(
    `https://admin.googleapis.com/admin/directory/v1/users/${encodeURIComponent(binding?.directoryId ?? identity.email)}`,
  );
  url.searchParams.set("viewType", "domain_public");
  url.searchParams.set("fields", "id,primaryEmail,name(fullName),thumbnailPhotoUrl");
  const profile = profileSchema.parse(await googleGet(url.toString(), accessToken));
  if (
    profile.primaryEmail.toLowerCase() !== identity.email.toLowerCase() ||
    (binding && profile.id !== binding.directoryId)
  )
    throw new WorkspaceUnavailable(true);

  if (!binding) {
    await db
      .insert(workspaceIdentity)
      .values({ googleSubject: subject, directoryId: profile.id })
      .onConflictDoNothing();
    const [saved] = await db
      .select()
      .from(workspaceIdentity)
      .where(eq(workspaceIdentity.googleSubject, subject));
    if (saved?.directoryId !== profile.id) throw new WorkspaceUnavailable(true);
  }
  return profile;
}

export async function hasReviewerRole(accessToken: string, directoryId: string, roleId: string) {
  const url = new URL(
    "https://admin.googleapis.com/admin/directory/v1/customer/my_customer/roleassignments",
  );
  url.searchParams.set("userKey", directoryId);
  url.searchParams.set("includeIndirectRoleAssignments", "true");
  let pageToken: string | undefined;
  do {
    const response = await fetch(url, {
      headers: { Authorization: `Bearer ${accessToken}` },
      cache: "no-store",
      signal: AbortSignal.timeout(10_000),
    });
    if (!response.ok) {
      await logGoogleFailure(url, response);
      if (response.status === 403) return false;
      throw new WorkspaceUnavailable(response.status === 401);
    }
    const assignments = roleAssignmentsSchema.parse(await response.json());
    if (assignments.items?.some((item) => item.roleId === roleId)) return true;
    pageToken = assignments.nextPageToken;
    if (pageToken) url.searchParams.set("pageToken", pageToken);
  } while (pageToken);
  return false;
}
import type { getReviewAccess } from "@/lib/auth";
import { isWorkspaceEmailAvailable } from "@/lib/directory";
import { suggestWorkspaceEmail } from "@/lib/review";
import { WorkspaceUnavailable } from "@/lib/workspace";

export const workspaceEmailCollision =
  "That Workspace email is already in use. Choose a different address.";

export function json(body: unknown, status = 200) {
  return Response.json(body, { status, headers: { "Cache-Control": "no-store" } });
}

export function deniedResponse(status: Awaited<ReturnType<typeof getReviewAccess>>["status"]) {
  switch (status) {
    case "signed-out":
    case "reconnect":
      return json({ outcome: status }, 401);
    case "denied":
      return json({ outcome: status }, 403);
    case "unavailable":
      return json({ outcome: status }, 503);
    default:
      return undefined;
  }
}

// Maps a failed Google/Directory call to its reconnect or unavailable outcome.
export function failure(error: unknown) {
  if (error instanceof WorkspaceUnavailable)
    return json(
      { outcome: error.reconnect ? "reconnect" : "unavailable" },
      error.reconnect ? 401 : 503,
    );
  return json({ outcome: "unavailable" }, 503);
}

// Drizzle wraps driver errors, so the Postgres code may be on `cause`.
export function isUniqueViolation(error: unknown): boolean {
  if (typeof error !== "object" || !error) return false;
  if ("code" in error && error.code === "23505") return true;
  return "cause" in error && isUniqueViolation(error.cause);
}

// Adds the address to show in the review fields (saved, else suggested) and whether it clashes.
// `workspaceEmailTaken` is null when the Directory cannot answer.
export async function withWorkspaceEmail<
  T extends { givenName: string; familyName: string; workspaceEmail: string | null },
>(signup: T) {
  const domain = process.env.GOOGLE_WORKSPACE_DOMAIN;
  const proposed =
    signup.workspaceEmail ??
    (domain ? suggestWorkspaceEmail(signup.givenName, signup.familyName, domain) : "");
  let taken: boolean | null = null;
  if (proposed) {
    try {
      taken = !(await isWorkspaceEmailAvailable(proposed));
    } catch {
      // Unknown clash state; saving still re-checks.
    }
  }
  return {
    ...signup,
    workspaceEmail: proposed,
    workspaceEmailSaved: signup.workspaceEmail !== null,
    workspaceEmailTaken: taken,
    workspaceDomain: domain?.toLowerCase() ?? null,
  };
}
import { z } from "zod";

import { getReviewAccess } from "@/lib/auth";
import { isWorkspaceEmailAvailable, listManageableGroups } from "@/lib/directory";
import {
  acceptSignupRequest,
  getProvisioningProgress,
  provisionAcceptedRequest,
} from "@/lib/provisioning";
import { getReviewableSignupRequest, getSignupPlan } from "@/lib/review";
import {
  deniedResponse,
  failure,
  json,
  workspaceEmailCollision as collision,
} from "@/lib/review-http";

export async function POST(
  request: Request,
  context: RouteContext<"/api/review/requests/[id]/acceptance">,
) {
  const access = await getReviewAccess(request.headers);
  const denied = deniedResponse(access.status);
  if (denied || access.status !== "available") return denied;
  const { id } = await context.params;
  if (!z.uuid().safeParse(id).success) return json({ error: "Request not found." }, 404);

  try {
    // A repeated accept skips validation (its own address is "taken" by now) and just reports.
    if (!(await getProvisioningProgress(id))) {
      const signup = await getReviewableSignupRequest(id);
      if (!signup) return json({ error: "Request not found." }, 404);
      if (signup.status !== "verified")
        return json({ error: "This signup request is no longer available." }, 409);
      if (!signup.workspaceEmail)
        return json(
          { errors: { workspaceEmail: "Save a Workspace email before accepting." } },
          422,
        );

      // Directory answers are re-checked now; saved plans may be stale.
      const plan = await getSignupPlan(id);
      const manageable = new Set((await listManageableGroups()).map((group) => group.id));
      if (plan.groups.some((group) => !manageable.has(group.groupId)))
        return json(
          { errors: { groups: "Remove groups you can no longer manage before accepting." } },
          422,
        );
      if (!(await isWorkspaceEmailAvailable(signup.workspaceEmail)))
        return json({ errors: { workspaceEmail: collision } }, 409);

      // Losing a race is fine: the winner's outcome is reported below.
      await acceptSignupRequest(id, access.profile.id);
    }
    // No-op unless the request is still `accepted`, so a crash between the steps self-heals.
    await provisionAcceptedRequest(id);
    const progress = await getProvisioningProgress(id);
    if (!progress) return json({ error: "This signup request is no longer available." }, 409);
    return json({ progress });
  } catch (error) {
    return failure(error);
  }
}
import { z } from "zod";

import { getReviewAccess } from "@/lib/auth";
import {
  isWorkspaceEmailAvailable,
  listManageableGroups,
  type ManageableGroup,
} from "@/lib/directory";
import {
  getReviewableSignupRequest,
  getSignupPlan,
  saveSignupPlan,
  suggestWorkspaceEmail,
} from "@/lib/review";
import {
  deniedResponse,
  failure,
  isUniqueViolation,
  json,
  workspaceEmailCollision as collision,
} from "@/lib/review-http";
import { parsePlanInput } from "@/lib/review-input";

async function planResponse(
  signup: { givenName: string; familyName: string },
  id: string,
  domain: string,
  groups: ManageableGroup[],
) {
  const plan = await getSignupPlan(id);
  const workspaceEmail =
    plan.workspaceEmail ?? suggestWorkspaceEmail(signup.givenName, signup.familyName, domain);
  const manageable = new Set(groups.map((group) => group.id));
  return {
    workspaceEmail,
    saved: plan.workspaceEmail !== null,
    unavailable: workspaceEmail !== "" && !(await isWorkspaceEmailAvailable(workspaceEmail)),
    groups,
    selected: plan.groups.map((group) => ({ ...group, manageable: manageable.has(group.groupId) })),
  };
}

async function load(request: Request, context: RouteContext<"/api/review/requests/[id]/plan">) {
  const access = await getReviewAccess(request.headers);
  const denied = deniedResponse(access.status);
  if (denied) return denied;
  const { id } = await context.params;
  const domain = process.env.GOOGLE_WORKSPACE_DOMAIN;
  if (!z.uuid().safeParse(id).success) return json({ error: "Request not found." }, 404);
  if (!domain) return json({ outcome: "unavailable" }, 503);
  const signup = await getReviewableSignupRequest(id);
  if (!signup) return json({ error: "Request not found." }, 404);
  if (signup.status !== "verified")
    return json({ error: "This signup request is no longer available." }, 409);
  return { id, domain, signup };
}

export async function GET(
  request: Request,
  context: RouteContext<"/api/review/requests/[id]/plan">,
) {
  try {
    const loaded = await load(request, context);
    if (loaded instanceof Response) return loaded;
    const { id, domain, signup } = loaded;
    return json(await planResponse(signup, id, domain, await listManageableGroups()));
  } catch (error) {
    return failure(error);
  }
}

export async function PUT(
  request: Request,
  context: RouteContext<"/api/review/requests/[id]/plan">,
) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return json({ error: "Submit the plan again." }, 400);
  }
  try {
    const loaded = await load(request, context);
    if (loaded instanceof Response) return loaded;
    const { id, domain, signup } = loaded;
    const parsed = parsePlanInput(body, domain);
    if (!parsed.data) return json({ errors: parsed.errors }, 422);

    const choices = await listManageableGroups();
    const byId = new Map(choices.map((group) => [group.id, group]));
    const groups = parsed.data.groups.map((group) => ({
      group: byId.get(group.id),
      role: group.role,
    }));
    if (groups.some(({ group }) => !group))
      return json({ errors: { groups: "Choose only groups you can manage." } }, 422);
    // Directory is checked on every save, so a stale earlier answer is never trusted.
    if (!(await isWorkspaceEmailAvailable(parsed.data.workspaceEmail)))
      return json({ errors: { workspaceEmail: collision } }, 409);

    let saved: boolean;
    try {
      saved = await saveSignupPlan(id, {
        workspaceEmail: parsed.data.workspaceEmail,
        groups: groups.map(({ group, role }) => ({
          groupId: group!.id,
          groupEmail: group!.email,
          role,
        })),
      });
    } catch (error) {
      if (isUniqueViolation(error)) return json({ errors: { workspaceEmail: collision } }, 409);
      throw error;
    }
    if (!saved) return json({ error: "This signup request is no longer available." }, 409);
    return json(await planResponse(signup, id, domain, choices));
  } catch (error) {
    return failure(error);
  }
}

